class Solution { public int maximumSwap(int num){char[] digits=String.valueOf(num).toCharArray();int[] last=new int[10];for(int i=0;i<digits.length;i++)last[digits[i]-'0']=i;for(int i=0;i<digits.length;i++)for(int digit=9;digit>digits[i]-'0';digit--)if(last[digit]>i){char value=digits[i];digits[i]=(char)('0'+digit);digits[last[digit]]=value;return Integer.parseInt(new String(digits));}return num;} }
